PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY, json TEXT NOT NULL, seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS persons(id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), removed_at INTEGER, json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS persons_space ON persons(space_id);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), person_id TEXT NOT NULL REFERENCES persons(id), token_hash TEXT NOT NULL UNIQUE, revoked_at INTEGER, json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS devices_space ON devices(space_id);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), used_at INTEGER, json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS grants_space ON grants(space_id);
CREATE TABLE IF NOT EXISTS revocations(id INTEGER PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS revocations_space ON revocations(space_id);
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), kind TEXT NOT NULL, json TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_all ON channels(space_id) WHERE kind='all';
CREATE TABLE IF NOT EXISTS members(channel_id TEXT NOT NULL REFERENCES channels(id), person_id TEXT NOT NULL REFERENCES persons(id), PRIMARY KEY(channel_id, person_id));
CREATE INDEX IF NOT EXISTS members_person ON members(person_id, channel_id);
CREATE TABLE IF NOT EXISTS wrapped_keys(channel_id TEXT NOT NULL REFERENCES channels(id), epoch INTEGER NOT NULL, device_id TEXT NOT NULL REFERENCES devices(id), json TEXT NOT NULL, PRIMARY KEY(channel_id,epoch,device_id));
CREATE TABLE IF NOT EXISTS threads(id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), channel_id TEXT NOT NULL REFERENCES channels(id), activity INTEGER NOT NULL, closed_by TEXT, closed_at INTEGER, close_json TEXT);
CREATE INDEX IF NOT EXISTS threads_retention ON threads(space_id,activity);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, space_id TEXT NOT NULL, channel_id TEXT NOT NULL, thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE, seq INTEGER NOT NULL, author_person TEXT NOT NULL, json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_space_seq ON messages(space_id,seq);
CREATE INDEX IF NOT EXISTS messages_channel_thread_seq ON messages(channel_id,thread_id,seq);
CREATE INDEX IF NOT EXISTS messages_channel_seq ON messages(channel_id,seq);
CREATE TABLE IF NOT EXISTS reactions(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, person_id TEXT NOT NULL, handle TEXT NOT NULL, kind TEXT NOT NULL, json TEXT NOT NULL, PRIMARY KEY(message_id,person_id,handle,kind));
CREATE UNIQUE INDEX IF NOT EXISTS one_claim ON reactions(message_id) WHERE kind='claim';
CREATE INDEX IF NOT EXISTS claims_person ON reactions(person_id,kind);
CREATE TABLE IF NOT EXISTS cursors(person_id TEXT NOT NULL, thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE, seq INTEGER NOT NULL, PRIMARY KEY(person_id,thread_id));
CREATE TABLE IF NOT EXISTS events(space_id TEXT NOT NULL, seq INTEGER NOT NULL, channel_id TEXT, target_person TEXT, thread_id TEXT REFERENCES threads(id) ON DELETE CASCADE, json TEXT NOT NULL, PRIMARY KEY(space_id,seq));
CREATE TABLE IF NOT EXISTS blobs(id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), uploader TEXT NOT NULL REFERENCES devices(id), size INTEGER NOT NULL, created_at INTEGER NOT NULL, json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS blobs_space ON blobs(space_id,created_at);
CREATE TABLE IF NOT EXISTS blob_refs(blob_id TEXT NOT NULL REFERENCES blobs(id) ON DELETE CASCADE, thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE, PRIMARY KEY(blob_id,thread_id));
CREATE TABLE IF NOT EXISTS rate_buckets(device_id TEXT PRIMARY KEY REFERENCES devices(id), minute REAL NOT NULL, hour REAL NOT NULL, updated REAL NOT NULL);
CREATE TABLE IF NOT EXISTS blob_gc(id TEXT PRIMARY KEY);
CREATE INDEX IF NOT EXISTS messages_thread ON messages(thread_id,seq);
CREATE INDEX IF NOT EXISTS cursors_thread ON cursors(thread_id);
CREATE INDEX IF NOT EXISTS events_thread ON events(thread_id);
CREATE INDEX IF NOT EXISTS blob_refs_thread ON blob_refs(thread_id);

CREATE TABLE IF NOT EXISTS trust_pins(space_id TEXT PRIMARY KEY REFERENCES spaces(id), json TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_invite_person ON grants(space_id,json_extract(json,'$.record.data.person_id')) WHERE json_extract(json,'$.record.data.kind')='invite';

CREATE TABLE IF NOT EXISTS message_mentions(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, person_id TEXT NOT NULL, handle TEXT NOT NULL, PRIMARY KEY(message_id,person_id,handle));
CREATE INDEX IF NOT EXISTS mentions_person ON message_mentions(person_id,handle,message_id);
CREATE INDEX IF NOT EXISTS devices_person ON devices(person_id,space_id);
CREATE TABLE IF NOT EXISTS revocation_holds(device_id TEXT NOT NULL REFERENCES devices(id), holder_device TEXT NOT NULL REFERENCES devices(id), PRIMARY KEY(device_id,holder_device));
CREATE TABLE IF NOT EXISTS revocation_prepared(holder_device TEXT NOT NULL REFERENCES devices(id), target TEXT NOT NULL, root TEXT NOT NULL, json TEXT NOT NULL, PRIMARY KEY(holder_device,target,root));
CREATE TABLE IF NOT EXISTS histories(space_id TEXT NOT NULL REFERENCES spaces(id), root TEXT NOT NULL, json TEXT NOT NULL, PRIMARY KEY(space_id,root));
CREATE INDEX IF NOT EXISTS messages_author ON messages(space_id,author_person);
CREATE INDEX IF NOT EXISTS events_kind ON events(space_id,json_extract(json,'$.event.kind'));
